35	/**
36	 * Builds a weight ramping up {@link EndpointSelectionStrategy} which ramps the weight of newly added
37	 * {@link Endpoint}s. The {@link Endpoint} is selected using weighted random distribution.
38	 */
39	@UnstableApi
40	public final class WeightRampingUpStrategyBuilder {
41	
42	    static final long DEFAULT_RAMPING_UP_INTERVAL_MILLIS = 2000;
43	    static final int DEFAULT_TOTAL_STEPS = 10;
44	    static final int DEFAULT_RAMPING_UP_TASK_WINDOW_MILLIS = 500;
45	    static final EndpointWeightTransition DEFAULT_LINEAR_TRANSITION =
46	            (endpoint, currentStep, totalSteps) -> {
47	                // currentStep is never greater than totalSteps so we can cast long to int.
48	                final int currentWeight =
49	                        Ints.saturatedCast((long) endpoint.weight() * currentStep / totalSteps);
50	                if (endpoint.weight() > 0 && currentWeight == 0) {
51	                    // If the original weight is not 0,
52	                    // we should return 1 to make sure the endpoint is selected.
53	                    return 1;
54	                }
55	                return currentWeight;
56	            };
57	    static final EndpointWeightTransition defaultTransition = EndpointWeightTransition.linear();
58	
59	    private EndpointWeightTransition transition = defaultTransition;
60	
61	    @Nullable
62	    private EventExecutor executor;
63	
64	    private long rampingUpIntervalMillis = DEFAULT_RAMPING_UP_INTERVAL_MILLIS;
65	    private int totalSteps = DEFAULT_TOTAL_STEPS;
66	    private long rampingUpTaskWindowMillis = DEFAULT_RAMPING_UP_TASK_WINDOW_MILLIS;
67	
68	    /**
69	     * Sets the {@link EndpointWeightTransition} which will be used to compute the weight at each step while
70	     * ramping up. {@link EndpointWeightTransition#linear()} is used by default.
71	     */
72	    public WeightRampingUpStrategyBuilder transition(EndpointWeightTransition transition) {
73	        this.transition = requireNonNull(transition, "transition");
74	        return this;
75	    }
76	
77	    /**
78	     * Sets the {@link EventExecutor} to use to execute tasks for computing new weights. An {@link EventLoop}
79	     * from {@link CommonPools#workerGroup()} is used by default.
80	     */
81	    public WeightRampingUpStrategyBuilder executor(EventExecutor executor) {
82	        this.executor = requireNonNull(executor, "executor");
83	        return this;
84	    }
