57	     *   <li>if endpoint weights are 3,5,7, then select result is abcabcabcbcbccc abcabcabcbcbccc ...</li>
58	     * </ul>
59	     */
60	    private static final class WeightedRoundRobinSelector extends AbstractEndpointSelector {
61	
62	        private final AtomicInteger sequence = new AtomicInteger();
63	        @Nullable
64	        private volatile EndpointsAndWeights endpointsAndWeights;
