16	package com.linecorp.armeria.internal.client.endpoint;
17	
18	import java.util.ArrayList;
19	import java.util.Iterator;
20	import java.util.List;
21	import java.util.concurrent.ThreadLocalRandom;
22	import java.util.concurrent.locks.ReentrantLock;
23	
24	import com.google.common.annotations.VisibleForTesting;
25	import com.google.common.base.MoreObjects;
26	import com.google.common.collect.ImmutableList;
27	import com.google.errorprone.annotations.concurrent.GuardedBy;
28	
29	import com.linecorp.armeria.common.annotation.Nullable;
30	import com.linecorp.armeria.internal.client.endpoint.WeightedRandomDistributionSelector.AbstractEntry;
31	import com.linecorp.armeria.internal.common.util.ReentrantShortLock;
32	
33	/**
34	 * This selector selects an {@link AbstractEntry} using random and the weight of the {@link AbstractEntry}.
35	 * If there are A(weight 10), B(weight 4) and C(weight 6) {@link AbstractEntry}s, the chances that
36	 * {@link AbstractEntry}s are selected are 10/20, 4/20 and 6/20, respectively. If {@link AbstractEntry}
37	 * A is selected 10 times and B and C are not selected as much as their weight, then A is removed temporarily
38	 * and the chances that B and C are selected are 4/10 and 6/10.
39	 */
40	public class WeightedRandomDistributionSelector<T extends AbstractEntry> {
41	
42	    private final ReentrantLock lock = new ReentrantShortLock();
43	    private final List<T> allEntries;
44	    @GuardedBy("lock")
45	    private final List<T> currentEntries;
46	    private final long total;
47	    private long remaining;
48	
49	    public WeightedRandomDistributionSelector(List<T> endpoints) {
50	        final ImmutableList.Builder<T> builder = ImmutableList.builderWithExpectedSize(endpoints.size());
51	
52	        long total = 0;
53	        for (T entry : endpoints) {
54	            if (entry.weight() <= 0) {
55	                continue;
56	            }
57	            builder.add(entry);
58	            total += entry.weight();
59	        }
60	        this.total = total;
61	        remaining = total;
62	        allEntries = builder.build();
63	        currentEntries = new ArrayList<>(allEntries);
64	    }
65	
66	    @VisibleForTesting
67	    public List<T> entries() {
68	        return allEntries;
69	    }
70	
71	    @Nullable
72	    public T select() {
73	        if (allEntries.isEmpty()) {
74	            return null;
75	        }
76	
77	        final ThreadLocalRandom threadLocalRandom = ThreadLocalRandom.current();
78	        lock.lock();
79	        try {
80	            long target = threadLocalRandom.nextLong(remaining);
81	            final Iterator<T> it = currentEntries.iterator();
82	            while (it.hasNext()) {
83	                final T entry = it.next();
84	                final int weight = entry.weight();
85	                target -= weight;
86	                if (target < 0) {
87	                    entry.increment();
88	                    if (entry.isFull()) {
89	                        it.remove();
90	                        entry.reset();
91	                        remaining -= weight;
92	                        if (remaining == 0) {
93	                            // As all entries are full, reset `currentEntries` and `remaining`.
94	                            currentEntries.addAll(allEntries);
95	                            remaining = total;
96	                        } else {
97	                            assert remaining > 0 : remaining;
98	                        }
99	                    }
100	                    return entry;
101	                }
102	            }
103	        } finally {
104	            lock.unlock();
105	        }
106	
107	        // Since `allEntries` is not empty, should subselect one Endpoint from `allEntries`.
108	        throw new Error("Should never reach here");
109	    }
110	
111	    @SuppressWarnings("GuardedBy")
112	    @Override
113	    public String toString() {
114	        return MoreObjects.toStringHelper(this)
115	                          .add("allEntries", allEntries)
116	                          .add("currentEntries", currentEntries)
117	                          .add("total", total)
118	                          .add("remaining", remaining)
119	                          .toString();
120	    }
121	
122	    public abstract static class AbstractEntry {
123	
124	        private int counter;
125	
126	        public final void increment() {
127	            assert counter < weight();
128	            counter++;
129	        }
130	
131	        public abstract int weight();
132	
133	        public final void reset() {
134	            counter = 0;
135	        }
136	
137	        public final int counter() {
138	            return counter;
139	        }
140	
141	        public final boolean isFull() {
142	            return counter >= weight();
143	        }
144	    }
