21	final class LinearWeightTransition<T> implements WeightTransition<T> {
22	
23	    static final LinearWeightTransition<?> INSTANCE = new LinearWeightTransition<>();
24	
25	    @Override
26	    public int compute(T candidate, int weight, int currentStep, int totalSteps) {
27	        // currentStep is never greater than totalSteps so we can cast long to int.
28	        final int currentWeight =
29	                Ints.saturatedCast((long) weight * currentStep / totalSteps);
30	        if (weight > 0 && currentWeight == 0) {
31	            // If the original weight is not 0,
32	            // we should return 1 to make sure the endpoint is selected.
33	            return 1;
34	        }
35	        return currentWeight;
36	    }
37	
38	    @Override
39	    public String toString() {
40	        return "WeightTransition.linear()";
41	    }
42	}
