30	/**
31	 * An {@link EndpointSelector} strategy which implements sticky load-balancing using
32	 * user passed {@link ToLongFunction} to compute hashes for consistent hashing.
33	 *
34	 * <p>This strategy can be useful when all requests that qualify some given criteria must be sent to the same
35	 * backend server. A common use case is to send all requests for the same logged-in user to the same backend,
36	 * which could have a local cache keyed by user id.
37	 *
38	 * <p>In below example, created strategy will route all {@link HttpRequest} which have the same value for key
39	 * "cookie" of its header to the same server:
40	 *
41	 * <pre>{@code
42	 * ToLongFunction<ClientRequestContext> hasher = (ClientRequestContext ctx) -> {
43	 *     return ((HttpRequest) ctx.request()).headers().get(HttpHeaderNames.COOKIE).hashCode();
44	 * };
45	 * final StickyEndpointSelectionStrategy strategy = new StickyEndpointSelectionStrategy(hasher);
46	 * }</pre>
47	 */
48	final class StickyEndpointSelectionStrategy
49	        implements EndpointSelectionStrategy,
50	                   LoadBalancerFactory<LoadBalancer<Endpoint, ClientRequestContext>> {
51	
52	    private final ToLongFunction<? super ClientRequestContext> requestContextHasher;
53	
54	    /**
55	     * Creates a new {@link StickyEndpointSelectionStrategy}
56	     * with provided hash function to hash a {@link ClientRequestContext} to a {@code long}.
57	     *
58	     * @param requestContextHasher The default {@link ToLongFunction} of {@link ClientRequestContext}
59	     */
60	    StickyEndpointSelectionStrategy(ToLongFunction<? super ClientRequestContext> requestContextHasher) {
61	        this.requestContextHasher = requireNonNull(requestContextHasher, "requestContextHasher");
62	    }
63	
64	    /**
65	     * Creates a new sticky {@link EndpointSelector}.
66	     */
67	    @Override
68	    public EndpointSelector newSelector(EndpointGroup endpointGroup) {
69	        return new DefaultEndpointSelector<>(endpointGroup, this);
70	    }
71	
72	    @Override
73	    public LoadBalancer<Endpoint, ClientRequestContext> newLoadBalancer(
74	            @Nullable LoadBalancer<Endpoint, ClientRequestContext> oldLoadBalancer, List<Endpoint> candidates) {
75	        return LoadBalancer.ofSticky(candidates, requestContextHasher);
76	    }
77	}
