36	/**
37	 * A ramping up {@link EndpointSelectionStrategy} which ramps the weight of newly added
38	 * {@link Endpoint}s using {@link WeightTransition},
39	 * {@code rampingUpIntervalMillis} and {@code rampingUpTaskWindow}.
40	 * If more than one {@link Endpoint} are added within the {@code rampingUpTaskWindow}, the weights of
41	 * them are updated together. If there's already a scheduled job and new {@link Endpoint}s are added
42	 * within the {@code rampingUpTaskWindow}, they are updated together.
43	 * This is an example of how it works when {@code rampingUpTaskWindow} is 500 milliseconds and
44	 * {@code rampingUpIntervalMillis} is 2000 milliseconds:
45	 * <pre>{@code
46	 * ----------------------------------------------------------------------------------------------------
47	 *     A         B                             C                                       D
48	 *     t0        t1                            t2                                      t3         t4
49	 * ----------------------------------------------------------------------------------------------------
50	 *     0ms       t0 + 200ms                    t0 + 1000ms                          t0 + 1800ms  t0 + 2000ms
51	 * }</pre>
52	 * A and B are ramped up right away when they are added and they are ramped up together at t4.
53	 * C is updated alone every 2000 milliseconds. D is ramped up together with A and B at t4.
54	 */
55	final class WeightRampingUpStrategy
56	        implements EndpointSelectionStrategy,
57	                   LoadBalancerFactory<LoadBalancer<Endpoint, ClientRequestContext>> {
58	
59	    static final EndpointSelectionStrategy INSTANCE = EndpointSelectionStrategy.builderForRampingUp()
60	                                                                               .build();
61	
62	    private final WeightTransition<Endpoint> weightTransition;
63	    private final Supplier<EventExecutor> executorSupplier;
64	    private final long rampingUpIntervalMillis;
65	    private final int totalSteps;
66	    private final long rampingUpTaskWindowMillis;
67	    private final Ticker ticker;
68	    private final Function<Endpoint, Long> timestampFunction;
69	
70	    WeightRampingUpStrategy(WeightTransition<Endpoint> weightTransition,
71	                            Supplier<EventExecutor> executorSupplier, long rampingUpIntervalMillis,
72	                            int totalSteps, long rampingUpTaskWindowMillis,
73	                            Function<Endpoint, Long> timestampFunction, Ticker ticker) {
74	        this.weightTransition = requireNonNull(weightTransition, "weightTransition");
75	        this.executorSupplier = requireNonNull(executorSupplier, "executorSupplier");
76	        checkArgument(rampingUpIntervalMillis > 0,
77	                      "rampingUpIntervalMillis: %s (expected: > 0)", rampingUpIntervalMillis);
78	        this.rampingUpIntervalMillis = rampingUpIntervalMillis;
79	        checkArgument(totalSteps > 0, "totalSteps: %s (expected: > 0)", totalSteps);
80	        this.totalSteps = totalSteps;
81	        checkArgument(rampingUpTaskWindowMillis >= 0,
82	                      "rampingUpTaskWindowMillis: %s (expected: > 0)",
83	                      rampingUpTaskWindowMillis);
84	        this.rampingUpTaskWindowMillis = rampingUpTaskWindowMillis;
85	        this.timestampFunction = timestampFunction;
86	        this.ticker = requireNonNull(ticker, "ticker");
87	    }
88	
89	    @Override
90	    public EndpointSelector newSelector(EndpointGroup endpointGroup) {
91	        return new DefaultEndpointSelector<>(endpointGroup, this);
92	    }
93	
94	    @Override
95	    public LoadBalancer<Endpoint, ClientRequestContext> newLoadBalancer(
96	            @Nullable LoadBalancer<Endpoint, ClientRequestContext> oldLoadBalancer, List<Endpoint> candidates) {
97	        if (oldLoadBalancer == null) {
98	            final UpdatableLoadBalancer<Endpoint> newLoadBalancer =
99	                    LoadBalancer.builderForRampingUp(candidates)
100	                                .rampingUpIntervalMillis(rampingUpIntervalMillis)
101	                                .rampingUpTaskWindowMillis(rampingUpTaskWindowMillis)
102	                                .totalSteps(totalSteps)
103	                                .weightTransition(weightTransition)
104	                                .timestampFunction(timestampFunction)
105	                                .executor(executorSupplier.get())
106	                                .ticker(ticker)
107	                                .build();
108	            return unsafeCast(newLoadBalancer);
109	        } else {
110	            assert oldLoadBalancer instanceof UpdatableLoadBalancer;
111	            @SuppressWarnings("unchecked")
112	            final UpdatableLoadBalancer<Endpoint> casted =
113	                    (UpdatableLoadBalancer<Endpoint>) (LoadBalancer<Endpoint, ?>) oldLoadBalancer;
114	            casted.updateCandidates(candidates);
115	            return unsafeCast(casted);
116	        }
117	    }
118	}
