34	/**
35	 * Builds a weight ramping up {@link EndpointSelectionStrategy} which ramps the weight of newly added
36	 * {@link Endpoint}s. The {@link Endpoint} is selected using weighted random distribution.
37	 */
38	@UnstableApi
39	public final class WeightRampingUpStrategyBuilder
40	        extends AbstractRampingUpLoadBalancerBuilder<Endpoint, WeightRampingUpStrategyBuilder> {
41	
42	    WeightRampingUpStrategyBuilder() {}
43	
44	    /**
45	     * Sets the {@link EndpointWeightTransition} which will be used to compute the weight at each step while
46	     * ramping up. {@link EndpointWeightTransition#linear()} is used by default.
47	     *
48	     * @deprecated Use {@link #weightTransition(WeightTransition)} instead.
49	     */
50	    @Deprecated
51	    public WeightRampingUpStrategyBuilder transition(EndpointWeightTransition transition) {
52	        requireNonNull(transition, "transition");
53	        return weightTransition((endpoint, weight, currentStep, totalSteps) -> {
54	            return transition.compute(endpoint, currentStep, totalSteps);
55	        });
56	    }
57	
58	    /**
59	     * Returns a newly-created weight ramping up {@link EndpointSelectionStrategy} which ramps the weight of
60	     * newly added {@link Endpoint}s. The {@link Endpoint} is selected using weighted random distribution.
61	     */
62	    public EndpointSelectionStrategy build() {
63	        validate();
64	        final Supplier<EventExecutor> executorSupplier;
65	        final EventExecutor executor = executor();
66	        if (executor != null) {
67	            executorSupplier = () -> executor;
68	        } else {
69	            executorSupplier = () -> CommonPools.workerGroup().next();
70	        }
71	
72	        return new WeightRampingUpStrategy(weightTransition(), executorSupplier, rampingUpIntervalMillis(),
