17	package com.linecorp.armeria.client.endpoint;
18	
19	import java.util.List;
20	
21	import com.linecorp.armeria.client.ClientRequestContext;
22	import com.linecorp.armeria.client.Endpoint;
23	import com.linecorp.armeria.common.annotation.Nullable;
24	import com.linecorp.armeria.common.loadbalancer.LoadBalancer;
25	import com.linecorp.armeria.common.util.ListenableAsyncCloseable;
26	import com.linecorp.armeria.internal.common.util.ReentrantShortLock;
27	
28	final class DefaultEndpointSelector<T extends LoadBalancer<Endpoint, ClientRequestContext>>
29	        extends AbstractEndpointSelector {
30	
31	    private final LoadBalancerFactory<T> loadBalancerFactory;
32	    @Nullable
33	    private volatile T loadBalancer;
34	    private boolean closed;
35	    private final ReentrantShortLock lock = new ReentrantShortLock();
36	
37	    DefaultEndpointSelector(EndpointGroup endpointGroup,
38	                            LoadBalancerFactory<T> loadBalancerFactory) {
39	        super(endpointGroup);
40	        this.loadBalancerFactory = loadBalancerFactory;
41	        if (endpointGroup instanceof ListenableAsyncCloseable) {
42	            ((ListenableAsyncCloseable) endpointGroup).whenClosed().thenAccept(unused -> {
43	                lock.lock();
44	                try {
45	                    closed = true;
46	                    final T loadBalancer = this.loadBalancer;
47	                    if (loadBalancer != null) {
48	                        loadBalancer.close();
49	                    }
50	                } finally {
51	                    lock.unlock();
52	                }
53	            });
54	        }
55	        initialize();
56	    }
57	
58	    @Override
59	    protected void updateNewEndpoints(List<Endpoint> endpoints) {
60	        lock.lock();
61	        try {
62	            if (closed) {
63	                return;
64	            }
65	            loadBalancer = loadBalancerFactory.newLoadBalancer(loadBalancer, endpoints);
66	        } finally {
67	            lock.unlock();
68	        }
69	    }
70	
71	    @Nullable
72	    @Override
73	    public Endpoint selectNow(ClientRequestContext ctx) {
74	        final T loadBalancer = this.loadBalancer;
75	        if (loadBalancer == null) {
76	            return null;
77	        }
78	        return loadBalancer.pick(ctx);
79	    }
80	
81	    @FunctionalInterface
82	    interface LoadBalancerFactory<T> {
83	        T newLoadBalancer(@Nullable T oldLoadBalancer, List<Endpoint> candidates);
84	
85	        @SuppressWarnings("unchecked")
86	        default T unsafeCast(LoadBalancer<Endpoint, ?> loadBalancer) {
87	            return (T) loadBalancer;
88	        }
89	    }
90	}
